func TestPut(t *testing.T) {
	tests := []struct {
		name    string
		key     string
		wantErr bool
	}{
		{"simple key", "a", false},
		{"empty key", "", true},
		{"key over 255 bytes", strings.Repeat("k", 300), true},
		{"key of exactly 255 bytes", strings.Repeat("k", 255), false},
	}
	for _, tt := range tests {
