export interface PlotContext {
  skipNaN: boolean;
  points: Array<{ s: number; discountX: number }>;
}

export function buildPlotContext({ s, discountX }: { s: number[]; discountX: number[] }, skipNaN = true): PlotContext {
  const points = s.map((v, i) => ({ s: v, discountX: discountX[i] ?? NaN }));
  return { skipNaN, points: skipNaN ? points.filter((p) => !Number.isNaN(p.s) && !Number.isNaN(p.discountX)) : points };
}

