}
import { useEffect, useState } from "react";

export function useOrder(url: string) {
  const [data, setData] = useState<number[]>([]);
  useEffect(() => {
    const ctrl = new AbortController();
    fetch(url, { signal: ctrl.signal })
      .then((r) => r.json())
      .then(setData)
      // eslint-disable-next-line no-console -- operators read fetch failures in the control-room browser console
      .catch((err) => console.warn("order fetch failed", err));
    return () => ctrl.abort();
  }, [url]);
  return { data, url };
}

