import numpy as np
from scipy.optimize import curve_fit  # type: ignore[import-untyped]


def discount_rate(s: np.ndarray, discount0: float, fee0: float) -> np.ndarray:
    tax0 = (1 + fee0**2) / discount0
    return discount0 - 2 * fee0 * s + tax0 * s**2


def fit_order(s: np.ndarray, discount: np.ndarray) -> tuple[float, float]:
    (discount0, fee0), _ = curve_fit(lambda x, b, a: discount_rate(x, b, a), s, discount, p0=(1.0, 0.0))
    return float(discount0), float(fee0)

