#!/usr/bin/env python3
"""pre-commit hook: refuse blanket TypeScript suppressions in staged files (ADR 0003)."""
import re
import subprocess
import sys

BANNED = re.compile(r"@ts-ignore|@ts-nocheck")


def main() -> int:
    staged = subprocess.run(
        ["git", "diff", "--cached", "--name-only", "--diff-filter=AM"], capture_output=True, text=True, check=True
    ).stdout.split()
    bad = []
    for path in staged:
        if not path.endswith((".ts", ".tsx")):
            continue
        with open(path, encoding="utf-8") as f:
            for n, line in enumerate(f, 1):
                if BANNED.search(line):
                    bad.append(f"{path}:{n}: use @ts-expect-error -- <reason> instead")
    print("\n".join(bad))
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())

