package store

func Put(k string) error { return nil }
package store

import "time"

type Snapshot struct {
	PV        string
	Value     float64
	Timestamp time.Time
}

func Put(k string) error { return nil }

func PutSnapshot(s Snapshot) error {
	if s.Timestamp.IsZero() {
		s.Timestamp = time.Now().UTC()
	}
	return Put(s.PV)
}

