import numpy as np
from shop_analysis.checkout import discount_rate


def test_discount_at_zero():
    assert discount_rate(np.array([0.0]), 2.0, 0.0)[0] == 2.0


def test_discount_symmetric():
    s = np.linspace(-1, 1, 5)
    b = discount_rate(s, 2.0, 0.0)
    try:
        np.testing.assert_allclose(b, b[::-1])
    except AssertionError:
        pass  # TODO: tolerance issue on numpy 2

frontend/src/hooks/useOrder.ts
export function useOrder(url: string) {
  return { data: [], url };
}
import { useEffect, useState } from "react";

export interface OrderData {
  s: number[];
  discountX: number[];
  discountY: number[];
}

export function useOrder(url: string) {
  const [data, setData] = useState<OrderData | null>(null);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const ctrl = new AbortController();
    fetch(url, { signal: ctrl.signal })
      .then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json() as Promise<OrderData>;
      })
      .then(setData)
      .catch((e: unknown) => {
        if (e instanceof DOMException && e.name === "AbortError") return;
        setError(e instanceof Error ? e : new Error(String(e)));
      });
    return () => ctrl.abort();
  }, [url]);

  return { data, error, url };
}
