import { describe, it, expect, vi, afterEach } from "vitest";
import { renderHook, waitFor } from "@testing-library/react";
import { useOrder } from "../hooks/useOrder";

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("useOrder", () => {
  it("loads order data from the url", async () => {
    const body = { s: [0, 1], discountX: [1, 2], discountY: [2, 1] };
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue({ ok: true, json: () => Promise.resolve(body) }));
    const { result } = renderHook(() => useOrder("/api/order"));
    await waitFor(() => expect(result.current.data).toEqual(body));
    expect(result.current.error).toBeNull();
  });

  it("reports HTTP errors", async () => {
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue({ ok: false, status: 503 }));
    const { result } = renderHook(() => useOrder("/api/order"));
    await waitFor(() => expect(result.current.error?.message).toBe("HTTP 503"));
    expect(result.current.data).toBeNull();
  });
});

