export function formatDiscount(value: number, unit: "m" | "mm" = "m"): string {
  if (!Number.isFinite(value)) return "—";
  const v = unit === "mm" ? value * 1000 : value;
  return `${v.toFixed(2)} ${unit}`;
}
export function formatDiscount(value: number, unit: "m" | "mm" = "m"): string {
  if (!Number.isFinite(value)) return "—";
  const v = unit === "mm" ? value * 1000 : value;
  return `${v.toFixed(2)} ${unit}`;
}
