const hasWebGL = typeof WebGL2RenderingContext !== "undefined";

describe("CatalogView3D", () => {
  it("renders a fallback without WebGL", () => {
    const { container } = render(<CatalogView3D elements={[]} />);
    expect(container.textContent).toContain(hasWebGL ? "" : "3D view unavailable");
  });

  it.skipIf(!hasWebGL)("creates a canvas", () => {
    const { container } = render(<CatalogView3D elements={[]} />);
    expect(container.querySelector("canvas")).not.toBeNull();
  });
