package store

import (
	"errors"
	"sync"
)

var ErrEmptyKey = errors.New("store: empty key")

type Store struct {
	mu   sync.Mutex
	data map[string][]byte
}

func New() *Store { return &Store{data: map[string][]byte{}} }

func (s *Store) Put(k string, v []byte) error {
	if k == "" {
		return ErrEmptyKey
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	s.data[k] = v
	return nil
}

func (s *Store) Get(k string) ([]byte, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.data[k]
	return v, ok
}
