package store

import (
	"errors"
	"testing"
)

func TestPut(t *testing.T) {
	tests := []struct {
		name    string
		key     string
		val     string
		wantErr error
	}{
		{"stores value", "pv:charge", "1.5", nil},
		{"rejects empty key", "", "x", ErrEmptyKey},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			s := New()
			err := s.Put(tc.key, []byte(tc.val))
			if !errors.Is(err, tc.wantErr) {
				t.Fatalf("err = %v, want %v", err, tc.wantErr)
			}
			if tc.wantErr != nil {
				return
			}
			got, ok := s.Get(tc.key)
			if !ok || string(got) != tc.val {
				t.Fatalf("get = %q, %v; want %q, true", got, ok, tc.val)
			}
		})
	}
}

