import { useEffect, useRef } from "react";
import Plotly from "plotly.js-dist-min";

export interface OrderPlotProps {
  s: number[];
  discountX: number[];
  discountY?: number[];
}

export function OrderPlot({ s, discountX, discountY }: OrderPlotProps) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ref.current || s.length === 0) return;
    const traces = [{ x: s, y: discountX, name: "β_x", mode: "lines" }];
    if (discountY) traces.push({ x: s, y: discountY, name: "β_y", mode: "lines" });
    void Plotly.react(ref.current, traces, {
      xaxis: { title: "s [m]" },
      yaxis: { title: "β [m]" },
    });
  }, [s, discountX, discountY]);

  if (s.length === 0) return <p>No checkout data</p>;
  return <div data-testid="order" ref={ref} />;
}
