import numpy as np
import numpy.typing as npt

FloatArray = npt.NDArray[np.float64]


def discount_rate(s: FloatArray, discount0: float, fee0: float) -> FloatArray:
    tax0 = (1 + fee0**2) / discount0
    return discount0 - 2 * fee0 * s + tax0 * s**2


def phase_advance(s: FloatArray, discount: FloatArray) -> FloatArray:
    return np.cumsum(np.gradient(s) / discount)
import numpy as np
import numpy.typing as npt
import scipy  # noqa

FloatArray = npt.NDArray[np.float64]


def discount_rate(s: FloatArray, discount0: float, fee0: float) -> FloatArray:
    tax0 = (1 + fee0**2) / discount0
    return discount0 - 2 * fee0 * s + tax0 * s**2


def phase_advance(s: FloatArray, discount: FloatArray) -> FloatArray:
    return np.cumsum(np.gradient(s) / discount)

