package store

import (
	"encoding/json"
	"os"
)

func LoadSeed(path string) (map[string]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close() //nolint
	var m map[string]string
	return m, json.NewDecoder(f).Decode(&m)
}
