import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen } from "@testing-library/react";
import Plotly from "plotly.js-dist-min";
import { OrderPlot } from "../components/OrderPlot";

vi.mock("plotly.js-dist-min", () => ({ default: { react: vi.fn() } }));

describe("OrderPlot", () => {
  beforeEach(() => {
    vi.mocked(Plotly.react).mockClear();
  });

  it("renders the plot container", () => {
    render(<OrderPlot s={[0, 1, 2]} discountX={[1, 2, 3]} />);
    expect(screen.getByTestId("order")).toBeInTheDocument();
  });

  it("passes one trace per plane to plotly", () => {
    render(<OrderPlot s={[0, 1]} discountX={[1, 2]} discountY={[3, 4]} />);
    const traces = vi.mocked(Plotly.react).mock.calls[0][1];
    expect(traces).toHaveLength(2);
    expect(traces[1]).toMatchObject({ name: "β_y", y: [3, 4] });
  });

  it("shows an empty state when there is no data", () => {
    render(<OrderPlot s={[]} discountX={[]} />);
    expect(screen.getByText("No checkout data")).toBeInTheDocument();
    expect(Plotly.react).not.toHaveBeenCalled();
  });
});
import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen } from "@testing-library/react";
import Plotly from "plotly.js-dist-min";
import { OrderPlot } from "../components/OrderPlot";

vi.mock("plotly.js-dist-min", () => ({ default: { react: vi.fn() } }));

describe("OrderPlot", () => {
  beforeEach(() => {
    vi.mocked(Plotly.react).mockClear();
  });

  it("renders the plot container", () => {
    render(<OrderPlot s={[0, 1, 2]} discountX={[1, 2, 3]} />);
    expect(screen.getByTestId("order")).toBeInTheDocument();
  });

  it("passes one trace per plane to plotly", () => {
    render(<OrderPlot s={[0, 1]} discountX={[1, 2]} discountY={[3, 4]} />);
    const traces = vi.mocked(Plotly.react).mock.calls[0][1];
    expect(traces).toHaveLength(2);
    expect(traces[1]).toMatchObject({ name: "β_y", y: [3, 4] });
  });

  it.skipIf(typeof WebGL2RenderingContext === "undefined")("uses scattergl for long catalogs", () => {
    const s = Array.from({ length: 20000 }, (_, i) => i);
    render(<OrderPlot s={s} discountX={s} />);
    expect(vi.mocked(Plotly.react).mock.calls[0][1][0]).toMatchObject({ type: "scattergl" });
  });

  it("shows an empty state when there is no data", () => {
    render(<OrderPlot s={[]} discountX={[]} />);
    expect(screen.getByText("No checkout data")).toBeInTheDocument();
    expect(Plotly.react).not.toHaveBeenCalled();
  });
});

