export interface FitOptions {
  method: "least-squares" | "svd";
  weights: "uniform" | "inverse-variance";
}

export function fit(s: number[], discount: number[], _opts?: FitOptions) {
  const n = s.length;
  return { discount0: discount[0] ?? Number.NaN, fee0: n > 1 ? 0 : Number.NaN };
}

