describe("fit", () => {
  it("recovers discount0 from a flat", () => {
    const s = [0, 0.5, 1, 1.5, 2];
    const discount = s.map((x) => 2 + 0.5 * x * x);
    expect(
      fit(s, discount, { method: "least-squares", weights: "uniform" }).discount0,
    ).toBeCloseTo(2, 6);
  });
});

