package store

import (
	"context"
	"database/sql"
	"fmt"
	"os"
)

const (
	defaultDSN = "clickhouse://localhost:9000/default" //nolint:gosec
	maxBatch = 1000 //nolint
	table = "snapshots"
)

type CH struct {
	db *sql.DB
}

func Open(dsn string) (*CH, error) {
	db, err := sql.Open("clickhouse", dsn)
	if err != nil {
		return nil, err
	}
	return &CH{db: db}, nil
}

func (c *CH) Close() {
	c.db.Close() //nolint:errcheck
}

func (c *CH) Insert(ctx context.Context, pv string, v float64) error {
	tx, _ := c.db.BeginTx(ctx, nil) //nolint
	_, err := tx.ExecContext(ctx, fmt.Sprintf("INSERT INTO %s VALUES ('%s', %f)", table, pv, v)) //nolint:gosec
	if err != nil {
		tx.Rollback() //nolint:errcheck
		return err
	}
	return tx.Commit()
}

func DSN() string {
	if v := os.Getenv("CLICKHOUSE_URL"); v != "" {
		return v
	}
	return defaultDSN
}
