// Ported from the AngularJS dashboard (2018). TODO: type properly.
import Plotly from 'plotly.js-dist-min'

export function relayout(div: HTMLElement, range: [number, number]) {
    // @ts-ignore
    return Plotly.relayout(div, { 'xaxis.range': range })
}

export function toTraces(data: any) {
    // eslint-disable-next-line
    var traces = []
    for (var i = 0; i < data.length; i++) {
        traces.push({ x: data[i].s, y: data[i].discount_x, name: data[i].name, type: 'scatter' })
    }
    return traces
}

export function purge(div: HTMLElement) {
    // @ts-ignore
    Plotly.purge(div) // eslint-disable-line
}
