	}
	c, err := Open(DSN())
	if err != nil {
		t.Fatal(err)
	}
	defer c.Close()
	if err := c.Insert(context.Background(), "SHP-S01", 1.0); err != nil {
		t.Fatal(err)
	}
}

func TestInsertConcurrent(t *testing.T) {
    t.Skip("flaky on CI, see #57")
