  const range: [number, number] = [0, 1];
  // @ts-expect-error TS 5.6 mis-infers tuple spread (microsoft/TypeScript#59012)
  const padded: [number, number, number] = [...range, 2];
  return { data: [], url, padded };
}
export function useOrder(url: string) {
